GimCorpus.put(437,0,[[1,3,"ואזהרה של מעילה מזה וכו'. א\"א ופשוטה מזו היא בתרומת הקדשים לא תאכל:",1,0],[1,5,"שלא הביא אשמו לא יצא. א\"א אינו משוה עם הגמרא של פרק הגוזל רבה:",1,0],[2,11,"יצא לנחל קדרון. א\"א אותה מעילה אינה אלא מדרבנן והכי איתא ביומא:",1,0],[3,12,"יהיה הקדש לוולדות הקדשים. א\"א ואם יאמר יהיה הקדש לולדות מה יועיל אלא יזמין ולא יקדיש:",1,0],[4,2,"ואם נפדה אין מועלין בפדיונו. א\"א למה אין מועלין בפדיונו אטו קדושת דמים מי לית ביה מעילה ואולי יאמר משום דאינו ראוי לפדיון שמא אינו רשאי לפדותו כשהוא תם:",1,0],[5,6,"ערבה הגדילה. א\"א זה שיבוש שלא נאמר במשנה אלא על אותה ערבה של אותה מקום שהיתה למטה מירושלים שייחדוה לשם מצוה:",1,0],[5,9,"והוא הגוף הקשה. א\"א אינו כן אלא העלה הנובל שהרי שנינו שהנביה נושרת עליהן והווה להן לזבל:",1,0],[6,2,"קדשי קדשים התמימים. א\"א זה אמרו מעצמו ואין לו סמך לא ממשנה ולא מתוספתא ולא מגמרא והלא לא חלקו במשנה אלא בין חטאת חיה למתה שאין פגם למתה אבל בחיה לא חלקו כלל. ומה שאמר אין לו טעם שהקרבן התמים אע\"פ שהוא עומד לקרבן אפשר שיפול בו מום ויפגם וימכר ועוד שהעור לכהנים הוא והוא נפגם אצלם שקודם זריקה מועלין בכלן והוא דבר שיש בו פגם:",1,0],[6,4,"ואין מועל אחר מועל במוקדשין. א\"א בכל זה יצא מכלל משנתנו וטעה אחר התוספתא כי אין במשנתנו אלא בהמה וכלי שרת ובודאי בהמה תמימה דומיא דכלי שרת והוא מפני שמצא בתוספתא בקע בקורדום ובא חבירו ובקע בו שניהם מעלו שינה הלשון וכתב בהמה וכלי תשמיש ופירש הבהמה חמור ואינו אלא בהמה תמימה למזבח דומיא דכלי שרת שהן למזבח ואין להם פדיון אבל כלי המוקדשין אם הראשון נהנה בו ופגם שוב אין בו מועל. ואין סומכין על תוספתא שהיא סותרת המשנה והגמרא:",1,0],[6,5,"וכן אם נתנה לחבירו. א\"א דבר זה לא נמצא לו יסוד. שמצא בתוספתא נטל פרוטה של הקדש ואמר הרי היא שלי לא אמר כלום עד שיוציאנה לחולין נתנו לספר אע\"פ שלא סיפר מעל ובעולה נתנו לחבירו וחבירו לחבירו כולן מעלו. זאת מצא ואיני סומך עליה כי לא באה על דרך מתוקן ואפשר מפני שהיא קדושת הגוף אינה יוצאה לחולין לא בפגימה ולא בנתינה אבל קשה לי מ\"ש עולה:",1,0],[6,7,"ונתנה לחבירו שניהם מעלו. א\"א אף בזה עזב כל הדרך הסלולה ותפס דרך הסירים שאין זה פירוש ההלכה אלא כמו שאפרש לפנים:",1,0],[6,8,"נטל אבן או קורה. א\"א זו היא שהעמיד בגמרא בגזבר שהכל תחת ידו שנטילתו אינה ניכרת לגזל ההקדש וכן כל אדם שהקדשו תחת ידו הרי הוא הגזבר ולא מעל עד שיוציא. ומה שהקשו בגמרא מ\"ש הוא ומ\"ש חבירו לא ר\"ל שימעלו הוא וחבירו אלא ה\"ק מ\"ש כשגנבה מבית ההקדש ונטלה לעצמו שלא מעל וכשנתנה לחבירו מעל אטו שינוי רשות בעינן למעילה והראשון מעל והשני לא מעל ושני ליה אי בשנטלה מבית הקדש ה\"נ שהוא מעל מיד ואם נתנה לחבירו אותו חבר לא מעל אלא הכא בגזבר שנטלה מרשות עצמו עסקינן שנטילתו אינו ניכר חסרון להקדש עד שיוציאנה לאחר:",1,0],[6,13,"בין הוא בין חבירו מעל. א\"א זהו מן הטעות הראשון:",1,0],[7,2,"אבל אם היו בשר עולה. א\"א תוספתא היא במעילה ויפה פירש. עוד אומר בה גם אני מפני שהעולה אינה נעשית חתיכות אלא מנתחה איברים איברים כדאיתא בתמיד וכדתנן בשקלים בשר שנמצא בעזרה איברים עולה וחתיכות חטאת הילכך אלו שראו אותה חתיכות היה להם לטעות של חטאת הם וכאנוסים דמו דלא הוה להו לשיולי אבל האוכל חייב שהוא נהנה. וראוי לסמוך עליו:",1,0]]);
